class Solution:
    def carFleet(self, target: int, position: list[int], speed: list[int]) -> int:
        cars = sorted(zip(position, speed), reverse=True)  # closest to target first
        stack: list[float] = []  # arrival times of the fleets so far
        for i, (p, s) in enumerate(cars):
            t = (target - p) / s  # viz:time
            if stack and t <= stack[-1]:
                continue  # viz:join
            stack.append(t)  # viz:new_fleet
        return len(stack)  # viz:done
